const TEXT: Readonly<Record<string, Readonly<Record<CanvasTextKey, string>>>> = {
    'zh-CN': ZH, 'zh-TW': ZH_TW, en: EN, ja: JA, ko: KO, es: ES, fr: FR, de: DE, 'pt-BR': PT_BR, ru: RU, ar: AR, hi: HI
};
export const COMIC_CANVAS_LOCALES = Object.keys(TEXT);

function uncheckedCanvasText(locale: string, key: CanvasTextKey, values?: Readonly<Record<string, string | number>>): string {
    const table = TEXT[locale] ?? (locale.startsWith('zh') ? TEXT['zh-CN'] : undefined);
    const raw = table?.[key];
    if (typeof raw !== 'string') throw new Error('missing');
    return raw.replace(/\{(\w+)\}/g, (match, name: string) => values && values[name] !== undefined ? String(values[name]) : match);
}

export function canvasText(locale: string, key: CanvasTextKey, ...rest: AfterLocaleAndKey<Parameters<typeof uncheckedCanvasText>>): string {
    return totalCopy(locale, key, language => uncheckedCanvasText(language, key, ...rest));
}

/** One capability or wiring problem in the user's language, naming the role/mode it is about. */
export function canvasIssueText(locale: string, issue: { readonly code: string; readonly path?: string }): string {
    const key = `issue.${issue.code}` as CanvasTextKey;
    const path = issue.path ?? '';
    const roleName = /inputs\.(\w+)/.exec(path)?.[1] ?? '';
    const role = roleName && (['prompt', 'firstFrame', 'lastFrame', 'referenceImage', 'referenceVideo', 'referenceAudio', 'character'] as const).includes(roleName as 'prompt')
        ? canvasText(locale, `role.${roleName}` as CanvasTextKey) : roleName.replace(/^reference/, '');
    const text = canvasText(locale, key, { role, path, mode: '' });
    return text === key ? canvasText(locale, 'unknown') : text;
}
